import { axios } from 'zyb-lib'
import { MessageBox, Message } from 'zyb-pc-ui'

const service = axios.create({
  baseURL: '/',
  timeout: 100000,
  withCredentials: true
})

service.interceptors.request.use(config => {
  return config
}, err => {
  console.log(err)
  return Promise.reject(err)
})

service.interceptors.response.use(res => {
  const data = res.data
  const config = res.config || {}
  const noTip = config.silence || false
  if (data) {
    if (data.status === 0) {
      return data
    } else if (data.status === 30001) {
      !noTip && Message.warning('请登录')
      localStorage.setItem('userInfo', '')
      location.reload();
    } else if (data.status === 30003) {
      location.assign(data.msg);
    } else {
      const msg = data.msg
      !noTip && MessageBox.alert(`${msg}`, {
        confirmButtonText: '确定'
      })
      return Promise.reject(data)
    }
  } else {
    !noTip && MessageBox.alert(`未知错误`, {
      confirmButtonText: '确定'
    })
    return Promise.reject(data)
  }
}, (err) => {
  if (err.response) {
    const res = err.response
    const { data } = res
    if (data) {
      MessageBox.alert('服务器开小差啦~', {
        confirmButtonText: '确定'
      })
      return Promise.reject(data)
    }
  } else {
    console.log(err)
    return Promise.reject(err)
  }
})

let io = {
  get: (...args) => {
    let method = 'get'
    let url = args[0]
    let params = args[1] || {}
    let headers = args[2] || {}
    return service({
      url,
      method,
      params,
      headers
    })
  },
  post: (...args) => {
    let method = 'post'
    let url = args[0]
    let data = args[1] || {}
    let headers = args[2] || {}
    let config = args[3] || {}
    return service({
      url,
      method,
      data,
      headers: {
        'Content-Type': 'application/json',
        ...headers
      },
      ...config
    })
  }
}

export default io
